            meta: { en: '4.5 km · 1 h 20 downhill · mid-June to October', fr: '4,5 km · 1 h 20 en descente · de mi-juin à octobre', de: '4,5 km · 1 Std. 20 abwärts · Mitte Juni bis Oktober' },
